  Future<void> _seedData(Database db) async {
    Future<void> ajouterMatiere(
      String niveau,
      String nomMatiere,
      List<_ChapitreSeed> chapitres,
    ) async {
      final matiereId = await db.insert('matieres', {
        'niveau': niveau,
        'nom': nomMatiere,
      });
      for (final chapitre in chapitres) {
        final chapitreId = await db.insert('chapitres', {
          'matiere_id': matiereId,
          'titre': chapitre.titre,
        });
        for (final carte in chapitre.cartes) {
          await db.insert('cartes_mentales', {
            'chapitre_id': chapitreId,
            'contenu': carte,
            'image': null,
          });
        }
        for (final q in chapitre.questions) {
          await db.insert('questions', {
            'chapitre_id': chapitreId,
            'enonce': q.enonce,
            'choix': jsonEncode(q.choix),
            'bonne_reponse': q.bonneReponse,
            'explication': q.explication,
            'niveau_complexite': q.niveauComplexite,
          });
        }
      }
    }

    // ══════════════════════════════════════════
    // MATIÈRES COMMUNES (Fondamental + Secondaire)
    // ══════════════════════════════════════════

    await ajouterMatiere('Commun', 'Communication Créole', [
      _ChapitreSeed(
          titre: 'Orthographe et phonologie du créole haïtien',
          cartes: [
          'Le créole haïtien a une orthographe phonémique officielle depuis 1979 : chaque son est représenté par un seul caractère.',
          'Les voyelles nasales en créole s\'écrivent avec un "n" après la voyelle : an, en, on, in.',
          'Le créole haïtien ne possède pas d\'accent écrit. L\'accent tonique tombe généralement sur la dernière syllabe.',
          'Les sons "ch" et "j" du français correspondent à "ch" et "j" en créole : "chache" (chercher), "jwèt" (jouet).',
          'Le "h" n\'est jamais muet en créole haïtien : "hat" se prononce comme en anglais.',
          ],
          questions: [
          _QSeed(
              'L\'orthographe officielle du créole haïtien fut établie en :',
              ['1979, par décret gouvernemental, et confirmée par la Constitution de 1987', '1804', '1961', '2000'],
              '1979, par décret gouvernemental, et confirmée par la Constitution de 1987',
              'Avant 1979, plusieurs orthographes coexistaient. L\'orthographe de 1979 (McConnell-Laubach-Pressoir révisée) est phonémique et systématique.',
              'Moyen',
            ),
          _QSeed(
              'En créole haïtien, le mot "manje" signifie :',
